class Counter {
    private val mutex = Mutex()
    private var value = 0

    suspend fun inc() = mutex.withLock { value++ }
    fun get(): Int = value
}

suspend fun run() = coroutineScope {
    val counter = Counter()
    repeat(4) { launch(Dispatchers.Default) { repeat(1000) { counter.inc() } } }
    println(counter.get())
}

// commonMain — a use case that moves work off the main thread
class FeedRepository(private val api: FeedApi) {
    suspend fun load(): List<FeedItem> = withContext(Dispatchers.Default) {
        api.fetch()
    }
}

// iosMain — UI updates must land on Dispatchers.Main
fun render(scope: CoroutineScope, repo: FeedRepository) {
    scope.launch {
        val items = repo.load()
        withContext(Dispatchers.Main) {
            uiController.render(items)   // runs on the main run loop
        }
    }
}

